<div class="toolbar"><span class="grow muted small">Build courses like a professional learning platform: sections, video and text lessons, downloads, quizzes, certificates and reviews.</span><a class="btn btn-primary btn-sm" href="/admin/courses/new"><?= icon('plus', 15) ?> New course</a></div>
<div class="table-wrap"><table class="t"><thead><tr><th>Course</th><th>Status</th><th>Instructor</th><th class="num">Lessons</th><th class="num">Learners</th><th>Rating</th><th></th></tr></thead><tbody>
<?php foreach ($items as $c): ?><tr><td><a href="/admin/courses/<?= (int) $c['id'] ?>"><strong><?= e($c['title']) ?></strong></a><div class="muted xs"><?= e($c['category_name']) ?> · <?= e(money($c['price'], $c['currency'])) ?></div></td><td><?= badge(ucfirst($c['status']), $c['status'] === 'published' ? 'green' : ($c['status'] === 'draft' ? 'amber' : '')) ?></td><td class="small"><?= e($c['instructor_name'] ?: '—') ?></td><td class="num"><?= (int) $c['lessons_count'] ?></td><td class="num"><?= (int) $c['enrol_count'] ?></td><td class="small"><?= $c['rating_count'] ? number_format((float) $c['rating_avg'], 1) . ' (' . (int) $c['rating_count'] . ')' : '—' ?></td>
<td class="tbl-actions"><a class="rowbtn" href="/admin/courses/<?= (int) $c['id'] ?>">Edit</a><a class="rowbtn" href="/admin/courses/<?= (int) $c['id'] ?>/learners">Learners</a><a class="rowbtn" target="_blank" href="/learning/<?= e($c['slug']) ?>">View</a></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="7" class="center muted" style="padding:34px">No courses yet. Create your first course.</td></tr><?php endif; ?></tbody></table></div>
<?php if (can('learning.manage')): ?><div class="two-eq mt3"><div class="panel"><div class="panel-h">Categories</div><div class="panel-b"><div class="chips"><?php foreach ($cats as $k): ?><form method="post" action="/admin/courses/categories" style="display:inline"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int) $k['id'] ?>"><span class="chip"><?= e($k['name']) ?> <button class="link danger" data-confirm="Remove this category?" title="Remove">×</button></span></form><?php endforeach; ?></div>
<form method="post" action="/admin/courses/categories" class="toolbar mt2" style="margin:0"><?= csrf_field() ?><input type="hidden" name="action" value="add"><input name="name" placeholder="New category" required><button class="btn btn-ghost btn-sm">Add</button></form></div></div>
<div class="panel"><div class="panel-h">Latest reviews</div><div class="panel-b"><?php foreach ($reviews as $r): ?><div style="display:flex;gap:10px;justify-content:space-between;border-bottom:1px solid #edf2ee;padding:8px 0"><div class="small"><strong><?= e($r['name']) ?></strong> · <?= (int) $r['rating'] ?>★ on <?= e($r['title']) ?><br><span class="muted"><?= e(excerpt($r['body'], 90)) ?></span></div><form method="post" action="/admin/reviews/<?= (int) $r['id'] ?>/toggle"><?= csrf_field() ?><button class="rowbtn"><?= $r['status'] === 'published' ? 'Hide' : 'Show' ?></button></form></div><?php endforeach; if (!$reviews) { echo '<span class="muted small">No reviews yet.</span>'; } ?></div></div></div><?php endif; ?>
